import re, sys

src = open('/challenge/CtfTask.v').read()
lines = src.split('\n')

def norm(s):
    s = s.strip()
    if s == "1'h0": return 'CONST0'
    if s == "1'h1": return 'CONST1'
    return s.replace('\\','').strip()

# ---------- parse module definitions ----------
moddefs = {}
i = 0
while i < len(lines):
    m = re.match(r'module\s+(\S+)\s*\(', lines[i])
    if m:
        name = m.group(1).replace('\\','')
        j = i+1
        assigns = []
        while j < len(lines) and not lines[j].strip().startswith('endmodule'):
            a = re.match(r'\s*assign\s+(.+?)\s*=\s*(.+?)\s*;', lines[j])
            if a:
                assigns.append((norm(a.group(1)), a.group(2).strip()))
            j += 1
        moddefs[name] = assigns
        i = j
    i += 1

# ---------- mini verilog expression parser ----------
# grammar: ternary lowest; then '|'; then '^'; then '&'; then unary '~'; atoms
def tokenize(s):
    toks = []
    k = 0
    while k < len(s):
        c = s[k]
        if c.isspace():
            k += 1; continue
        if c in '?:~&|^()':
            toks.append(c); k += 1; continue
        m = re.match(r"[A-Za-z0-9_$\[\]]+", s[k:])
        if m:
            toks.append(m.group(0)); k += len(m.group(0)); continue
        k += 1
    return toks

class ExprParser:
    def __init__(self, toks):
        self.t = toks; self.p = 0
    def peek(self): return self.t[self.p] if self.p < len(self.t) else None
    def eat(self):
        v = self.t[self.p]; self.p += 1; return v
    def parse_ternary(self):
        cond = self.parse_or()
        if self.peek() == '?':
            self.eat()
            a = self.parse_ternary()
            if self.peek() == ':':
                self.eat()
            b = self.parse_ternary()
            return ('if', cond, a, b)
        return cond
    def parse_or(self):
        l = self.parse_xor()
        while self.peek() == '|':
            self.eat(); r = self.parse_xor(); l = ('or', l, r)
        return l
    def parse_xor(self):
        l = self.parse_and()
        while self.peek() == '^':
            self.eat(); r = self.parse_and(); l = ('xor', l, r)
        return l
    def parse_and(self):
        l = self.parse_unary()
        while self.peek() == '&':
            self.eat(); r = self.parse_unary(); l = ('and', l, r)
        return l
    def parse_unary(self):
        if self.peek() == '~':
            self.eat(); return ('not', self.parse_unary())
        return self.parse_atom()
    def parse_atom(self):
        v = self.eat()
        if v == '(':
            e = self.parse_ternary()
            self.eat()  # ')'
            return e
        return ('var', v)

def eval_expr(e, env):
    t = e[0]
    if t == 'var':
        return env.get(e[1], 0)
    if t == 'not':
        return 1 - eval_expr(e[1], env)
    if t == 'and':
        return eval_expr(e[1], env) & eval_expr(e[2], env)
    if t == 'or':
        return eval_expr(e[1], env) | eval_expr(e[2], env)
    if t == 'xor':
        return eval_expr(e[1], env) ^ eval_expr(e[2], env)
    if t == 'if':
        return eval_expr(e[2], env) if eval_expr(e[1], env) else eval_expr(e[3], env)
    return 0

# precompile module defs into parsed expr lists
def compile_mod(assigns):
    out = []
    for lhs, rhs in assigns:
        out.append((lhs, ExprParser(tokenize(rhs)).parse_ternary()))
    return out

compiled = {k: compile_mod(v) for k, v in moddefs.items()}

def eval_module(name, ivals):
    """evaluate module 'name' with inputs I0..I5 in dict ivals. Returns dict lhs->val (incl 'O')."""
    env = dict(ivals)
    env['CONST0'] = 0; env['CONST1'] = 1
    assigns = compiled[name]
    # iterate to fixpoint
    for _ in range(200):
        changed = False
        for lhs, expr in assigns:
            v = eval_expr(expr, env)
            if env.get(lhs, -1) != v:
                env[lhs] = v; changed = True
        if not changed:
            break
    return env.get('O', 0)

# ---------- parse CtfTask body ----------
start = next(i for i,l in enumerate(lines) if l.startswith('module CtfTask'))
end = next(i for i in range(start+1,len(lines)) if lines[i].strip()=='endmodule')
body = lines[start:end+1]

instances = []
idx = 1
N = len(body)
while idx < N:
    s = body[idx].rstrip()
    if s.endswith('(') and not s.strip().startswith('wire') and not s.strip().startswith('input') and not s.strip().startswith('output'):
        header = s[:-1].strip()
        parts = header.split()
        typ = parts[0]
        iname = parts[-1] if len(parts)>1 else ''
        idx += 1
        pins = {}
        while idx < N and ');' not in body[idx]:
            p = body[idx].strip()
            if p.startswith('.'):
                mm = re.match(r'\.([A-Za-z0-9_]+)\s*\(\s*(.*?)\s*\)\s*,?\s*?$', p)
                if mm:
                    pins[mm.group(1)] = norm(mm.group(2))
            idx += 1
        instances.append((typ.replace('\\',''), iname, pins))
    idx += 1

# build gate list
combi = []   # list of callables: each takes env and returns (out_signal, value)
ffs = []     # (q_name, d_name, clr?) 

for typ, iname, pins in instances:
    nm = typ
    if 'LUT' in nm:
        mm = re.search(r'INIT=(\d+)', nm)
        m2 = re.search(r'LUT(\d)', nm)
        n = int(m2.group(1)) if m2 else 6
        O = pins.get('O')
        inps = [pins.get('I%d'%k) for k in range(n)]
        if mm:
            val = mm.group(1)
            mm2 = re.search(r"(\d+)'([01]+)", nm)
            init = int(mm2.group(2),2) if mm2 else int(val)
            def make(o, inps, init):
                def f(env):
                    idxv = 0
                    for k, s in enumerate(inps):
                        if s is not None and env.get(s,0): idxv |= (1<<k)
                    return (o, (init>>idxv)&1)
                return f
            combi.append(make(O, inps, init))
        else:
            # hashed LUT6, use module def
            def make(o, inps, modname):
                def f(env):
                    ivals = {'I%d'%k: env.get(inps[k],0) if inps[k] else 0 for k in range(6)}
                    v = eval_module(modname, ivals)
                    return (o, v)
                return f
            combi.append(make(O, inps, nm))
    elif nm == 'MUXCY':
        def f(env, p=pins):
            return (p.get('O'), env.get(p.get('CI'),0) if env.get(p.get('S'),0) else env.get(p.get('DI'),0))
        combi.append(f)
    elif nm in ('MUXF7','MUXF8'):
        def f(env, p=pins):
            return (p.get('O'), env.get(p.get('I1'),0) if env.get(p.get('S'),0) else env.get(p.get('I0'),0))
        combi.append(f)
    elif nm == 'XORCY':
        def f(env, p=pins):
            return (p.get('O'), env.get(p.get('CI'),0) ^ env.get(p.get('LI'),0))
        combi.append(f)
    elif 'FDCE' in nm:
        ffs.append((pins.get('Q'), pins.get('D'), pins.get('CLR')))
    elif 'FDPE' in nm:
        ffs.append((pins.get('Q'), pins.get('D'), None))

print("combi gates:", len(combi), "ffs:", len(ffs))

# collect all FF Q signals
ff_state = {}
for q, d, clr in ffs:
    ff_state[q] = 0

# collect signal names used as FF outputs (these are the sequential nodes)
ff_outputs = set(q for q,d,c in ffs)

def settle(env):
    # env: dict of input signals (clk,reset,io bits) + ff outputs -> value
    # compute combinational, iterate
    for _ in range(100):
        changed = False
        for gate in combi:
            o, v = gate(env)
            if env.get(o, -1) != v:
                env[o] = v; changed = True
        if not changed:
            break
    return env

def eval_ports(env):
    return env.get('io_power', 0)

# ---------- simulate one full run ----------
# inputs: list of 7 triplets (each 3 chars) -> but we drive byte by byte
# We'll drive bytes with inputDone pulses like the C++ harness.

def drive_byte(env, byte, clk_ref, reset):
    env['io_input'] = byte & 0x7f  # but io_input is 7 bits; we set bits individually
    # actually io_input is [6:0]; we'll store integer and map in settle

print("setup done")

