import re, sys

src = open('/challenge/CtfTask.v').read()
lines = src.split('\n')

def norm(s):
    s = s.strip()
    if s in ("1'h0","1'b0"): return '0'
    if s in ("1'h1","1'b1"): return '1'
    return s.replace('\\','').strip()

def tokenize(s):
    toks=[]; k=0
    while k<len(s):
        c=s[k]
        if c.isspace(): k+=1; continue
        if c in '?:~&|^()': toks.append(c); k+=1; continue
        m=re.match(r"[A-Za-z0-9_$\[\].']+", s[k:])
        if m: toks.append(m.group(0)); k+=len(m.group(0)); continue
        k+=1
    return toks

class P:
    def __init__(self,t): self.t=t; self.p=0
    def pk(self): return self.t[self.p] if self.p<len(self.t) else None
    def eat(self): v=self.t[self.p]; self.p+=1; return v
    def tern(self):
        c=self.orr()
        if self.pk()=='?':
            self.eat(); a=self.tern(); self.eat(); b=self.tern(); return ('if',c,a,b)
        return c
    def orr(self):
        l=self.xor()
        while self.pk()=='|': self.eat(); r=self.xor(); l=('or',l,r)
        return l
    def xor(self):
        l=self.andd()
        while self.pk()=='^': self.eat(); r=self.andd(); l=('xor',l,r)
        return l
    def andd(self):
        l=self.un()
        while self.pk()=='&': self.eat(); r=self.un(); l=('and',l,r)
        return l
    def un(self):
        if self.pk()=='~': self.eat(); return ('not',self.un())
        return self.atom()
    def atom(self):
        v=self.eat()
        if v=='(': e=self.tern(); self.eat(); return e
        return ('var',v)

def ev(e,env):
    t=e[0]
    if t=='var': return env.get(e[1],0)
    if t=='not': return 1-ev(e[1],env)
    if t=='and': return ev(e[1],env)&ev(e[2],env)
    if t=='or': return ev(e[1],env)|ev(e[2],env)
    if t=='xor': return ev(e[1],env)^ev(e[2],env)
    if t=='if': return ev(e[2],env) if ev(e[1],env) else ev(e[3],env)
    return 0

moddefs={}
i=0
while i<len(lines):
    m=re.match(r'module\s+(\S+)\s*\(', lines[i])
    if m:
        name=m.group(1).replace('\\','')
        j=i+1; assigns=[]
        while j<len(lines) and not lines[j].strip().startswith('endmodule'):
            a=re.match(r'\s*assign\s+(.+?)\s*=\s*(.+?)\s*;', lines[j])
            if a: assigns.append((norm(a.group(1)), P(tokenize(a.group(2))).tern()))
            j+=1
        moddefs[name]=assigns
        i=j
    i+=1

def eval_module(name, ivals):
    env=dict(ivals); env['0']=0; env['1']=1
    assigns=moddefs.get(name)
    if assigns is None: return None
    for _ in range(500):
        ch=False
        for lhs,expr in assigns:
            v=ev(expr,env)
            if env.get(lhs,-1)!=v: env[lhs]=v; ch=True
        if not ch: break
    return env.get('O',0)

start=next(i for i,l in enumerate(lines) if l.startswith('module CtfTask'))
end=next(i for i in range(start+1,len(lines)) if lines[i].strip()=='endmodule')
body=lines[start:end+1]

instances=[]
idx=1; N=len(body)
while idx<N:
    s=body[idx].rstrip()
    if s.endswith('(') and not re.match(r'\s*(wire|input|output|assign)\b', s):
        header=s[:-1].strip(); parts=header.split()
        typ=parts[0]; iname=parts[-1] if len(parts)>1 else ''
        idx+=1; pins={}

