import subprocess, sys

def run(inp):
    p = subprocess.run(['./VCtfTask'], input=inp.encode()+b'\n', capture_output=True, cwd='/work')
    return p.stdout.decode('latin1')

def analyze(inp):
    out = run(inp)
    r = {}
    r['failed'] = 'TEST FAILED' in out or 'NEEDS FURTHER' in out
    r['missed'] = 'SHUTDOWN MISSED' in out
    r['activated'] = 'SHUTDOWN ACTIVATED' in out
    # extract last Power Level and Before temp
    return r, out

if __name__ == '__main__':
    mode = sys.argv[1] if len(sys.argv)>1 else 'single'
    if mode == 'single':
        # test all 3-digit values as single input (0-999)
        found = []
        for v in range(1000):
            s = f'{v:03d}'
            r, out = analyze(s)
            if r['failed'] or r['missed']:
                found.append((s, r))
                print('FOUND', s, r)
        print('done single, found', len(found))
        # print a sample of what normal looks like for a few values
    elif mode == 'power':
        # dump power level vs input value to understand FSM
        for v in [0,50,99,100,123,124,200,254,255,256,999]:
            s = f'{v:03d}'
            r, out = analyze(s)
            lines = [l for l in out.split('\n') if 'Power' in l]
            print(v, lines[0] if lines else '?', 'FAIL' if r['failed'] else '')

